const canvas = document.querySelector('canvas')
const ctx = canvas.getContext('2d')
const koi = { x: 160, y: 240, tx: 160, ty: 240 }

canvas.addEventListener('pointermove', (e) => {
  koi.tx = e.offsetX
  koi.ty = e.offsetY
})

function frame() {
  koi.x += (koi.tx - koi.x) * 0.08
  koi.y += (koi.ty - koi.y) * 0.08

  ctx.fillStyle = '#1b2433'
  ctx.fillRect(0, 0, canvas.width, canvas.height)

  ctx.fillStyle = '#e8573c'
  ctx.beginPath()
  ctx.ellipse(koi.x, koi.y, 22, 10, 0, 0, Math.PI * 2)
  ctx.fill()

  requestAnimationFrame(frame)
}
requestAnimationFrame(frame)
